select * from new_three_simultaneous


    and org_code=#{orgCode}


    and stage=#{stage}



    and entry_name=#{entryName}



    and YEAR(archive_year) =#{file10}



    and archive_number like  CONCAT('%',#{archiveNumber},'%')



LIMIT #{begin}, #{limit};

